CREATE TYPE "Role" AS ENUM ('TEACHER','STUDENT');
CREATE TYPE "Status" AS ENUM ('PRESENT','LATE','ABSENT','EXCUSED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"password" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'STUDENT',CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LoginSession" ("hash" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LoginSession_pkey" PRIMARY KEY ("hash"));
CREATE TABLE "Course" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"color" TEXT NOT NULL DEFAULT '#8b5cf6',"joinCode" TEXT NOT NULL,"teacherId" TEXT NOT NULL,CONSTRAINT "Course_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Enrollment" ("courseId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Enrollment_pkey" PRIMARY KEY ("courseId","studentId"));
CREATE TABLE "ClassSession" ("id" TEXT NOT NULL,"courseId" TEXT NOT NULL,"title" TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endsAt" TIMESTAMP(3) NOT NULL,"closedAt" TIMESTAMP(3),"lateAfterMinutes" INTEGER NOT NULL,CONSTRAINT "ClassSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Attendance" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"status" "Status" NOT NULL,"source" TEXT NOT NULL,"checkedInAt" TIMESTAMP(3),CONSTRAINT "Attendance_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Audit" ("id" TEXT NOT NULL,"actorId" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"before" TEXT,"after" "Status" NOT NULL,"reason" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Audit_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "LoginSession_expiresAt_idx" ON "LoginSession"("expiresAt");
CREATE UNIQUE INDEX "Course_joinCode_key" ON "Course"("joinCode"); CREATE UNIQUE INDEX "Course_teacherId_code_key" ON "Course"("teacherId","code"); CREATE INDEX "ClassSession_courseId_startedAt_idx" ON "ClassSession"("courseId","startedAt"); CREATE UNIQUE INDEX "Attendance_sessionId_studentId_key" ON "Attendance"("sessionId","studentId");
ALTER TABLE "LoginSession" ADD CONSTRAINT "LoginSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Course" ADD CONSTRAINT "Course_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "User"("id") ON UPDATE CASCADE;
ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON UPDATE CASCADE; ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON UPDATE CASCADE;
ALTER TABLE "ClassSession" ADD CONSTRAINT "ClassSession_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON UPDATE CASCADE; ALTER TABLE "Attendance" ADD CONSTRAINT "Attendance_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "ClassSession"("id") ON UPDATE CASCADE; ALTER TABLE "Attendance" ADD CONSTRAINT "Attendance_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON UPDATE CASCADE; ALTER TABLE "Audit" ADD CONSTRAINT "Audit_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON UPDATE CASCADE;
